# Full receipts for my own run artifacts (the report itself is hashed externally after serialization).
receipts=[]
for p in sorted(run.rglob('*')):
    if p.is_file(): receipts.append({'path':rel(p),'sha256':digest(p),'bytes':p.stat().st_size})
report['artifact_receipts']=receipts
output=base/'report.json'
assert not output.exists(), 'Do not replace a prior report without preservation.'
output.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
loaded=json.loads(output.read_text())
assert loaded['verdict'] in ['pass','revise']
assert {x['file'] for x in loaded['documents']}==set(expected)
assert all(set(x['checks'])=={'background_and_links','terminology','examples','program_explanation','exercise'} for x in loaded['documents'])
for r in loaded['artifact_receipts']: assert digest(repo/r['path'])==r['sha256']
report_hash=digest(output)
(base/'report-sha256.txt').write_text(report_hash+'  '+rel(output)+'\n')
print(json.dumps({'report':rel(output),'sha256':report_hash,'verdict':loaded['verdict'],'assigned_sources':expected,'issues':loaded['issues'],'receipt_count':len(receipts),'all_own_artifact_hashes_match':True},ensure_ascii=False,indent=2))
